create function public.commit_ingestion_batch(p_id uuid,p_token uuid,p_jobs jsonb) returns integer language plpgsql security definer set search_path='' as $$ declare task public.ingestion_tasks%rowtype; board_row public.job_boards%rowtype; n integer; begin if jsonb_typeof(p_jobs) is distinct from 'array' or jsonb_array_length(p_jobs)>100 then raise exception 'Invalid batch'; end if; select * into task from public.ingestion_tasks where id=p_id and status='running' and lease_token=p_token and lease_until>now() for update; if not found then raise exception 'Lease lost'; end if; select * into board_row from public.job_boards where id=task.board_id and enabled; if not found then raise exception 'Board disabled'; end if; if exists(select 1 from jsonb_array_elements(p_jobs) j where jsonb_typeof(j) is distinct from 'object' or j->>'source' is distinct from board_row.source or left(coalesce(j->>'source_id',''),length(board_row.board)+1)<>board_row.board||':' or length(coalesce(j->>'source_id',''))>4096 or length(coalesce(j->>'title','')) not between 1 and 500 or length(coalesce(j->>'company','')) not between 1 and 200 or length(coalesce(j->>'location',''))>1000 or length(coalesce(j->>'description',''))>1000000 or coalesce(j->>'listing_url','') !~ '^https://') then raise exception 'Invalid listing'; end if; insert into public.jobs(source,source_id,title,company,location,description,listing_url,published_at,last_verified_at,active) select source,source_id,title,company,coalesce(location,''),coalesce(description,''),listing_url,published_at,last_verified_at,true from jsonb_to_recordset(p_jobs) as x(source text,source_id text,title text,company text,location text,description text,listing_url text,published_at timestamptz,last_verified_at timestamptz) on conflict(source,source_id) do update set title=excluded.title,company=excluded.company,location=excluded.location,description=excluded.description,listing_url=excluded.listing_url,published_at=excluded.published_at,last_verified_at=excluded.last_verified_at,active=true; get diagnostics n=row_count; return n; end $$;
revoke all on function public.commit_ingestion_batch(uuid,uuid,jsonb) from public; grant execute on function public.commit_ingestion_batch(uuid,uuid,jsonb) to service_role;
